              - bar

            # Task A
            "}),
        bare_options(),
        None,
    );

    let key: liwe::model::Key = "1".to_string().into();
    let meta = graph
        .get_metadata(&key)
        .expect("metadata should be parsed for bare frontmatter");

    assert!(
        meta.contains("- foo") && meta.contains("- bar"),
        "expected metadata to retain YAML sequence items, got: {meta:?}"
    );
}

